import numpy as np
from scipy import ndimage
d = np.load('source_pixels.npz')
rgb = d['rgb']
def track(f, cond):
    m = cond(f)
    lab,n = ndimage.label(m)
    out=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        if len(xs)>=4:
            out.append((len(xs),xs.mean(),ys.mean(),xs.min(),xs.max(),ys.min(),ys.max()))
    return sorted(out,reverse=True)
f=rgb[0]
r,g,b = f[:,:,0].astype(int), f[:,:,1].astype(int), f[:,:,2].astype(int)
print('red comps')
for c in track(f, lambda f:(f[:,:,0]>150)&(f[:,:,1]<90)&(f[:,:,2]<90))[:8]: print(c)
print('blue comps')
for c in track(f, lambda f:(f[:,:,2]>150)&(f[:,:,0]<120)&(f[:,:,1]<150))[:8]: print(c)
print('white comps')
for c in track(f, lambda f:(f[:,:,0]>225)&(f[:,:,1]>225)&(f[:,:,2]>225))[:8]: print(c)
\""
